PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
INSERT OR IGNORE INTO meta VALUES ('revision','0'),('schema_version','1'),('demo','false');
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS budget_years (year INTEGER PRIMARY KEY CHECK(year BETWEEN 2000 AND 2100), reference_units INTEGER NOT NULL CHECK(reference_units>=0), tax_basis TEXT NOT NULL DEFAULT 'excluded' CHECK(tax_basis='excluded')) STRICT;
CREATE TABLE IF NOT EXISTS budget_versions (id INTEGER PRIMARY KEY, year INTEGER NOT NULL REFERENCES budget_years(year), name TEXT NOT NULL CHECK(length(trim(name))>0), description TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)), created_at TEXT NOT NULL, budget_units INTEGER CHECK(budget_units>=0), UNIQUE(year,name)) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS one_active_version ON budget_versions(year) WHERE active=1;
CREATE TABLE IF NOT EXISTS budget_categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name))>0), name_key TEXT NOT NULL UNIQUE, sort_order INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS training_topics (id INTEGER PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name))>0), name_key TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE IF NOT EXISTS budget_lines (id INTEGER PRIMARY KEY, version_id INTEGER NOT NULL REFERENCES budget_versions(id), category_id INTEGER NOT NULL REFERENCES budget_categories(id), month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12), amount_units INTEGER NOT NULL CHECK(amount_units>=0), UNIQUE(version_id,category_id,month)) STRICT;
CREATE TABLE IF NOT EXISTS savings_items (id INTEGER PRIMARY KEY, version_id INTEGER NOT NULL REFERENCES budget_versions(id), title TEXT NOT NULL CHECK(length(trim(title))>0), amount_units INTEGER NOT NULL CHECK(amount_units>=0)) STRICT;
CREATE TABLE IF NOT EXISTS invoices (id INTEGER PRIMARY KEY, number TEXT NOT NULL CHECK(length(trim(number))>0), year INTEGER NOT NULL REFERENCES budget_years(year), month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12), note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS invoice_lines (id INTEGER PRIMARY KEY, invoice_id INTEGER NOT NULL REFERENCES invoices(id), category_id INTEGER NOT NULL REFERENCES budget_categories(id), training_name TEXT NOT NULL CHECK(length(trim(training_name))>0), amount_units INTEGER NOT NULL CHECK(amount_units>=0), foreign_units INTEGER CHECK(foreign_units>=0), currency TEXT NOT NULL DEFAULT '', rate_units INTEGER CHECK(rate_units>0), participant_count INTEGER NOT NULL CHECK(participant_count>=0), rd_participant_count INTEGER NOT NULL CHECK(rd_participant_count>=0), other_participant_count INTEGER NOT NULL CHECK(other_participant_count>=0), description TEXT NOT NULL DEFAULT '', CHECK(foreign_units IS NULL OR (currency IN ('USD','EUR','GBP','CHF') AND rate_units IS NOT NULL))) STRICT;
CREATE TABLE IF NOT EXISTS planned_payments (id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES budget_categories(id), year INTEGER NOT NULL REFERENCES budget_years(year), month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12), description TEXT NOT NULL CHECK(length(trim(description))>0), amount_units INTEGER NOT NULL CHECK(amount_units>0), saving_units INTEGER NOT NULL DEFAULT 0 CHECK(saving_units>=0 AND saving_units<=amount_units), saving_note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled'))) STRICT;
CREATE TABLE IF NOT EXISTS planned_payment_invoice_links (id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES planned_payments(id), line_id INTEGER NOT NULL REFERENCES invoice_lines(id), amount_units INTEGER NOT NULL CHECK(amount_units>0), UNIQUE(payment_id,line_id)) STRICT;
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS invoice_period ON invoices(year,month,status);
CREATE INDEX IF NOT EXISTS line_category ON invoice_lines(category_id,invoice_id);
CREATE INDEX IF NOT EXISTS payment_period ON planned_payments(year,month,status);
CREATE INDEX IF NOT EXISTS invoice_lines_invoice ON invoice_lines(invoice_id);
CREATE INDEX IF NOT EXISTS link_line ON planned_payment_invoice_links(line_id);
CREATE INDEX IF NOT EXISTS budget_line_category ON budget_lines(category_id);
CREATE INDEX IF NOT EXISTS payment_category ON planned_payments(category_id);
CREATE INDEX IF NOT EXISTS saving_version ON savings_items(version_id);
CREATE INDEX IF NOT EXISTS version_year ON budget_versions(year);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS session_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS audit_user ON audit_logs(user_id);
